import 'package:cloud_firestore/cloud_firestore.dart';
import '../business/business_repository.dart';
import '../../core/models/business.dart';
import '../goals/goal_repository.dart';
class AurenGrowthPlan{final String businessId,businessName,objective;final List<String> actions,metrics;final DateTime generatedAt;const AurenGrowthPlan({required this.businessId,required this.businessName,required this.objective,required this.actions,required this.metrics,required this.generatedAt});Map<String,dynamic> toMap()=>{'businessId':businessId,'businessName':businessName,'objective':objective,'actions':actions,'metrics':metrics,'generatedAt':Timestamp.fromDate(generatedAt.toUtc())};}
class BusinessGrowthService{final FirebaseFirestore _db;final BusinessRepository _businesses;final GoalRepository _goals;BusinessGrowthService({FirebaseFirestore? firestore,BusinessRepository? businesses,GoalRepository? goals}):_db=firestore??FirebaseFirestore.instance,_businesses=businesses??BusinessRepository(),_goals=goals??GoalRepository();Future<AurenGrowthPlan> build(String uid,{String? businessId})async{final bs=await _businesses.watchPublic().first;final owned=bs.where((x)=>x.ownerId==uid).toList();AurenBusiness? b;for(final x in owned){if(businessId==x.id){b=x;break;}}b??=(owned.isEmpty?null:owned.first);final goals=await _goals.watch(uid).first;final objective=goals.any((g)=>g.status=='active')?'ربط النمو بهدفك النشط التالي':'زيادة العملاء والوصول إلى فرص جديدة';final name=b?.name??'نشاطي التجاري';final city=b?.city.isNotEmpty==true?b!.city:'السوق المستهدف';final actions=b==null?['أنشئ صفحة Business عامة','أضف وصفًا واضحًا وخدمة أساسية','حدد العميل المستهدف','أنشئ أول عرض قابل للقياس']:['حدد عرضًا واحدًا واضحًا لـ '+b!.name,'حدد 3 شرائح عملاء محتملة في '+city,'أنشئ قائمة فرص وشراكات مناسبة','اختبر رسالة تعريفية واحدة ثم قِس الاستجابة','حوّل النتائج إلى خطوة نمو تالية'];final metrics=['عدد العملاء المحتملين المؤهلين','نسبة الاستجابة','عدد المحادثات أو الفرص الجديدة','طلبات الخدمة أو الشراء','تحويل الفرص إلى عملاء'];final plan=AurenGrowthPlan(businessId:b?.id??'',businessName:name,objective:objective,actions:actions,metrics:metrics,generatedAt:DateTime.now());await _db.collection('users').doc(uid).collection('business_growth_plans').doc('current').set(plan.toMap());return plan;}}